package com.doms.doms.controller;
import com.doms.doms.dto.AuditResponse;import com.doms.doms.entity.*;import com.doms.doms.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/audit") @RequiredArgsConstructor public class AuditController{
 private final AuditLogRepository logs;private final UserRepository users;private User current(){return users.findByEmail(SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow();}
 @GetMapping public List<AuditResponse> list(@RequestParam(required=false)String from,@RequestParam(required=false)String to,@RequestParam(required=false)String action){User u=current();List<AuditLog> rows;if((from!=null&&!from.isBlank())||(to!=null&&!to.isBlank())){LocalDate a=from==null||from.isBlank()?LocalDate.of(1970,1,1):LocalDate.parse(from);LocalDate b=to==null||to.isBlank()?LocalDate.now():LocalDate.parse(to);rows=logs.findByUserAndCreatedAtBetweenOrderByCreatedAtDesc(u,a.atStartOfDay(),b.plusDays(1).atStartOfDay().minusNanos(1));}else rows=logs.findTop200ByUserOrderByCreatedAtDesc(u);return rows.stream().filter(x->action==null||action.isBlank()||x.getAction().equalsIgnoreCase(action)).map(x->new AuditResponse(x.getId(),x.getAction(),x.getDocumentId(),x.getDocumentCode(),x.getDocumentName(),x.getDetails(),x.getCreatedAt())).toList();}
}
